import time
def ttl_cache(seconds):
    def decorator(fn):
        cache = {}
        def wrapper(*args):
            now = time.time()
            if args in cache:
                value, expires = cache[args]
                if expires > now:
                    return value
            value = fn(*args)
            cache[args] = (value, now + seconds)
            return value
        return wrapper
    return decorator

